<?php
namespace App\Services\DevOps;use App\Models\{ZigoDeployment,ZigoHealthCheck,ZigoDevOpsAlert};
final class DevOpsReportService {public function metrics(array $filters=[]):array{$q=ZigoDeployment::query()->when($filters['environment']??null,fn($q,$v)=>$q->where('environment',$v))->when($filters['status']??null,fn($q,$v)=>$q->where('status',$v))->when($filters['user_id']??null,fn($q,$v)=>$q->where('requested_by_user_id',$v))->when($filters['branch']??null,fn($q,$v)=>$q->where('branch','like','%'.$v.'%'))->when($filters['commit']??null,fn($q,$v)=>$q->where('commit_hash','like',$v.'%'))->when($filters['from']??null,fn($q,$v)=>$q->whereDate('created_at','>=',$v))->when($filters['to']??null,fn($q,$v)=>$q->whereDate('created_at','<=',$v));$total=(clone$q)->count();$success=(clone$q)->where('status','success')->count();$healthTotal=ZigoHealthCheck::count();$durations=(clone$q)->whereNotNull('started_at')->whereNotNull('finished_at')->get(['started_at','finished_at'])->map(fn($d)=>$d->started_at->diffInSeconds($d->finished_at));return['total_deployments'=>$total,'successful_deployments'=>$success,'success_rate'=>$total?round($success*100/$total,2):0,'failed_deployments'=>(clone$q)->where('status','failed')->count(),'rollback_count'=>(clone$q)->where('status','rolled_back')->count(),'average_duration_seconds'=>$durations->isEmpty()?0:round((float)$durations->avg(),2),'migrations_executed'=>(clone$q)->where('summary','like','%"migration_applied":true%')->count(),'health_success_rate'=>$healthTotal?round(ZigoHealthCheck::where('status','success')->count()*100/$healthTotal,2):0,'open_alerts'=>ZigoDevOpsAlert::where('status','open')->count()];}}
